-- Markera alla ödekyrkogårdar som historiska platser utan känd sägen:
UPDATE places SET has_legend = false WHERE id LIKE 'odekyrkogard-%';
COMMIT;

-- ══════════ has_legend-omklassificering (motsvarar hauntedplaces 0112) ══════════
-- Svenska bulk-platser utan specifik sägen (avrättningsplatser, ödekyrkogårdar)
-- klassas som historiska. ISOF-sägner (sagen-%) undantas alltid.
UPDATE places SET has_legend = false
WHERE country = 'Sverige'
AND type IN ('Avrättningsplats','Ödekyrkogård','Pestkyrkogård','Kolerakyrkogård','Kyrkogård')
AND id NOT LIKE 'sagen-%';
